module decomposition_counter(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [4:0] exp0, exp1, exp2, exp3, exp4, exp5, exp6, exp7, exp8, exp9, exp10,\n    output reg [31:0] result,\n    output reg done\n);\n\n    parameter MOD = 1000000007;\n    parameter MAX_PRIMES = 11;\n\n    // State encoding\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COMPUTE_BINOM = 3'd1;\n    localparam [2:0] NUMERATOR_LOOP = 3'd2;\n    localparam [2:0] MULTIPLY = 3'd3;\n    localparam [2:0] MULTIPLY_INVERSE = 3'd4;\n    localparam [2:0] ACCUMULATE_RESULT = 3'd5;\n    localparam [2:0] UPDATE_RESULT = 3'd6;\n    localparam [2:0] DONE = 3'd7;\n\n    // Registers\n    reg [2:0] state;\n    reg [3:0] n_reg;\n    reg [4:0] exp_reg [0:MAX_PRIMES-1];\n    reg [31:0] numerator;\n    reg [31:0] binom;\n    reg [4:0] prime_index;\n    reg [3:0] loop_i;\n\n    // Multiplication unit signals\n    reg [31:0] mul_a, mul_b;\n    reg [31:0] mul_a_reg, mul_b_reg;\n    reg [31:0] mul_result;\n    reg [5:0] mul_count;\n    reg mul_start, mul_done;\n\n    // Inverse factorial lookup (indexed by n-1, so size 8 for n=1..8)\n    wire [31:0] inv_fact [0:7];\n    assign inv_fact[0] = 32'd1;                // inv(0!)\n    assign inv_fact[1] = 32'd1;                // inv(1!)\n    assign inv_fact[2] = 32'd500000004;        // inv(2!)\n    assign inv_fact[3] = 32'd166666668;        // inv(3!)\n    assign inv_fact[4] = 32'd41666667;         // inv(4!)\n    assign inv_fact[5] = 32'd808333337;        // inv(5!)\n    assign inv_fact[6] = 32'd201388893;        // inv(6!)\n    assign inv_fact[7] = 32'd35791429;         // inv(7!)\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            mul_start <= 1'b0;\n            mul_done <= 1'b0;\n            prime_index <= 5'd0;\n            loop_i <= 4'd0;\n            numerator <= 32'd0;\n            binom <= 32'd0;\n            mul_count <= 6'd0;\n            mul_a <= 32'd0;\n            mul_b <= 32'd0;\n            mul_a_reg <= 32'd0;\n            mul_b_reg <= 32'd0;\n            mul_result <= 32'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        n_reg <= n;\n                        exp_reg[0] <= exp0;\n                        exp_reg[1] <= exp1;\n                        exp_reg[2] <= exp2;\n                        exp_reg[3] <= exp3;\n                        exp_reg[4] <= exp4;\n                        exp_reg[5] <= exp5;\n                        exp_reg[6] <= exp6;\n                        exp_reg[7] <= exp7;\n                        exp_reg[8] <= exp8;\n                        exp_reg[9] <= exp9;\n                        exp_reg[10] <= exp10;\n                        result <= 32'd1;\n                        prime_index <= 5'd0;\n                        state <= COMPUTE_BINOM;\n                    end\n                end\n\n                COMPUTE_BINOM: begin\n                    if (prime_index < MAX_PRIMES) begin\n                        if (exp_reg[prime_index] > 0) begin\n                            numerator <= 32'd1;\n                            loop_i <= 4'd1;\n                            state <= NUMERATOR_LOOP;\n                        end else begin\n                            prime_index <= prime_index + 5'd1;\n                        end\n                    end else begin\n                        state <= DONE;\n                    end\n                end\n\n                NUMERATOR_LOOP: begin\n                    if (loop_i < n_reg) begin\n                        mul_a <= numerator;\n                        mul_b <= exp_reg[prime_index] + loop_i;\n                        mul_start <= 1'b1;\n                        state <= MULTIPLY;\n                    end else begin\n                        mul_a <= numerator;\n                        mul_b <= inv_fact[n_reg - 1];\n                        mul_start <= 1'b1;\n                        state <= MULTIPLY_INVERSE;\n                    end\n                end\n\n                MULTIPLY: begin\n                    if (mul_start) mul_start <= 1'b0;\n                    if (mul_done) begin\n                        numerator <= mul_result;\n                        loop_i <= loop_i + 4'd1;\n                        state <= NUMERATOR_LOOP;\n                        mul_done <= 1'b0;\n                    end\n                end\n\n                MULTIPLY_INVERSE: begin\n                    if (mul_start) mul_start <= 1'b0;\n                    if (mul_done) begin\n                        binom <= mul_result;\n                        state <= ACCUMULATE_RESULT;\n                        mul_done <= 1'b0;\n                    end\n                end\n\n                ACCUMULATE_RESULT: begin\n                    mul_a <= result;\n                    mul_b <= binom;\n                    mul_start <= 1'b1;\n                    state <= UPDATE_RESULT;\n                end\n\n                UPDATE_RESULT: begin\n                    if (mul_start) mul_start <= 1'b0;\n                    if (mul_done) begin\n                        result <= mul_result;\n                        prime_index <= prime_index + 5'd1;\n                        state <= COMPUTE_BINOM;\n                        mul_done <= 1'b0;\n                    end\n                end\n\n                DONE: begin\n                    done <= 1'b1;\n                    if (!start) state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n\n            // Multiplication unit (32-cycle shift-add)\n            if (mul_start) begin\n                mul_count <= 6'd32;\n                mul_result <= 32'd0;\n                mul_b_reg <= mul_b;\n                mul_a_reg <= mul_a;\n            end else if (mul_count > 0) begin\n                // Add if LSB of multiplier is 1\n                if (mul_b_reg[0]) begin\n                    if (mul_result + mul_a_reg >= MOD)\n                        mul_result <= mul_result + mul_a_reg - MOD;\n                    else\n                        mul_result <= mul_result + mul_a_reg;\n                end\n                // Double multiplicand\n                mul_a_reg <= {mul_a_reg[30:0], 1'b0};\n                if (mul_a_reg >= MOD)\n                    mul_a_reg <= mul_a_reg - MOD;\n                // Shift multiplier\n                mul_b_reg <= mul_b_reg >> 1;\n                mul_count <= mul_count - 1;\n            end else if (mul_count == 0 && (state == MULTIPLY || state == MULTIPLY_INVERSE || state == UPDATE_RESULT)) begin\n                mul_done <= 1'b1;\n            end\n        end\n    end\nendmodule